def _assets(assets) -> str:
    return " + ".join(escape(asset.label) for asset in assets)


def manager_context_selection(teams: list[dict], *, workflow: str | None = None) -> str:
    """Render an explicit franchise chooser instead of guessing manager identity."""
    destination = "/trades" if not workflow else f"/trades/{escape(workflow, quote=True)}"
    options = "".join(
        f'<option value="{int(team.get("roster_id") or 0)}">{escape(str(team.get("team_name") or team.get("owner") or "Unassigned Franchise"))}</option>'
        for team in teams
    )
    return f'''{TRADE_CSS}<section class="card ti-hero"><div><div class="identity-kicker">Trade Center · Manager Context</div><h2>Choose your franchise</h2><p>DTOS needs an explicit league-scoped manager before it can use ownership, roster fit, or bilateral trade intelligence.</p></div></section><section class="card"><form method="get" action="{destination}"><label for="front_office">Controlled franchise</label><select id="front_office" name="front_office" required><option value="" selected disabled>Choose a franchise</option>{options}</select><div class="ti-actions"><button class="ti-action" type="submit">Continue to Trade Center</button></div></form><p class="muted">No commissioner, first-roster, or named-manager fallback is applied.</p></section>'''


def _premium_trade_enhancement() -> str:
    """Load the asset-first mobile layer after initial page readiness."""
    return '''<style>
.ti-roster-browser{margin:18px 0}.ti-target-hero{text-align:left;display:grid;grid-template-columns:110px 1fr;align-items:center;gap:4px 20px;margin:14px 0 20px;padding:20px 24px;border:1px solid rgba(93,242,55,.28);border-radius:20px;background:radial-gradient(circle at 90% 10%,rgba(93,242,55,.15),transparent 30%),linear-gradient(145deg,#102536,#08131e)}.ti-target-hero>img,.ti-target-hero>.ti-pick-icon{grid-row:1/5;width:110px;height:110px;margin:0;border-radius:18px;object-fit:cover}.ti-target-hero h3{font-size:32px;margin:0}.ti-target-hero p{margin:0;font-size:16px}.ti-target-hero small,.ti-target-hero>span:first-child{color:var(--muted)}.ti-browser-controls,.ti-position-filters{display:flex;gap:7px;overflow-x:auto;margin:9px 0}.ti-browser-controls button,.ti-position-filters button{min-height:38px;border:1px solid var(--line);border-radius:999px;background:#07111f;color:var(--muted);padding:6px 12px}.ti-browser-controls button[aria-pressed="true"],.ti-position-filters button[aria-pressed="true"]{color:#07111f;background:var(--accent);border-color:var(--accent)}.ti-browser-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.ti-roster-group{display:grid;gap:7px;align-content:start}.ti-roster-group[hidden],.ti-asset-tile[hidden]{display:none}.ti-asset-tile{display:grid;grid-template-columns:42px 1fr auto;gap:9px;align-items:center;min-height:58px;padding:7px;text-align:left;color:var(--text);background:#07111f;border:1px solid var(--line);border-radius:11px}.ti-asset-tile[aria-pressed="true"]{outline:2px solid var(--accent);background:#102c3b}.ti-asset-tile img,.ti-pick-icon{width:42px;height:42px;border-radius:9px;object-fit:cover;background:#16283f}.ti-pick-icon{display:grid;place-items:center;color:var(--gold);font-size:9px;font-weight:900}.ti-asset-tile span,.ti-asset-tile b,.ti-asset-tile small{display:block}.ti-asset-tile small{color:var(--muted)}.ti-asset-tile strong{color:var(--accent)}.ti-market-balance{display:grid;gap:7px;margin:14px 0;padding:14px;background:#0b1727;border-radius:13px}.ti-market-balance div{display:flex;justify-content:space-between}.ti-market-balance small{color:var(--muted)}@media(max-width:760px){.ti-target-hero{grid-template-columns:82px 1fr;padding:15px;gap:3px 12px}.ti-target-hero>img,.ti-target-hero>.ti-pick-icon{width:82px;height:82px}.ti-target-hero h3{font-size:24px}.ti-browser-grid{grid-template-columns:1fr}.ti-asset-tile{min-height:64px}}
</style><script>
window.addEventListener('load', async () => {
  const root = document.getElementById('trade-builder'); if (!root) return;
  const response = await fetch(root.dataset.workspaceEndpoint + '?front_office=' + root.dataset.frontOffice);
  const data = await response.json(), active = Number(root.dataset.frontOffice);
  const browser = document.createElement('section'); browser.className = 'ti-roster-browser';
  const title = document.createElement('h3'); title.textContent = 'League assets'; browser.append(title);
  const scope = document.createElement('div'); scope.className = 'ti-browser-controls'; scope.setAttribute('aria-label', 'Roster view'); browser.append(scope);
  let rosterScope = 'active', position = 'ALL';
  for (const [value, label] of [['active', 'YOUR TEAM'], ['partner', 'THEIR TEAM']]) { const button = document.createElement('button'); button.type = 'button'; button.textContent = label; button.dataset.scope = value; button.setAttribute('aria-pressed', String(value === rosterScope)); button.onclick = () => { rosterScope = value; [...scope.children].forEach(row => row.setAttribute('aria-pressed', String(row === button))); applyFilters(); }; scope.append(button); }
  const filter = document.createElement('input'); filter.type = 'search'; filter.placeholder = 'Filter player, position, rank, or pick'; filter.setAttribute('aria-label', 'Filter trade assets'); browser.append(filter);
  const positionFilters = document.createElement('div'); positionFilters.className = 'ti-position-filters'; positionFilters.setAttribute('aria-label', 'Position filters'); browser.append(positionFilters);
  for (const value of ['ALL', 'QB', 'RB', 'WR', 'TE', 'PICKS']) { const button = document.createElement('button'); button.type = 'button'; button.textContent = value; button.setAttribute('aria-pressed', String(value === position)); button.onclick = () => { position = value; [...positionFilters.children].forEach(row => row.setAttribute('aria-pressed', String(row === button))); applyFilters(); }; positionFilters.append(button); }
  const grid = document.createElement('div'); grid.className = 'ti-browser-grid'; browser.append(grid); root.querySelector('.ti-builder').before(browser);
  const values = new Map(), tiles = []; let targetItem = null, targetTeam = null;
  for (const team of data.teams) {
    const group = document.createElement('section'); group.className = 'ti-roster-group'; group.dataset.rosterId = String(team.roster_id);
    const heading = document.createElement('h4'); heading.textContent = team.roster_id === active ? 'Your roster' : team.team_name; group.append(heading);
    for (const item of team.assets) {
      values.set(item.label, Number(item.trade_value || 0));
      if (item.asset_id === root.dataset.preloadAsset) { targetItem = item; targetTeam = team; }
      const button = document.createElement('button'); button.type = 'button'; button.className = 'ti-asset-tile ' + (item.kind === 'pick' ? 'ti-pick-tile' : 'ti-player-tile');
      button.dataset.rosterId = String(team.roster_id); button.dataset.position = item.kind === 'pick' ? 'PICKS' : (item.position || ''); button.dataset.assetLabel = item.label; button.setAttribute('aria-pressed', 'false');
      if (item.kind === 'player' && item.headshot_url) { const image = document.createElement('img'); image.src = item.headshot_url; image.alt = ''; image.loading = 'lazy'; button.append(image); }
      else if (item.kind === 'player') { const icon = document.createElement('span'); icon.className = 'ti-pick-icon'; icon.textContent = item.position || 'NFL'; button.append(icon); }
      else { const icon = document.createElement('span'); icon.className = 'ti-pick-icon'; icon.textContent = 'PICK'; button.append(icon); }
      const identity = document.createElement('span'), name = document.createElement('b'), meta = document.createElement('small'), value = document.createElement('strong');
      name.textContent = item.raw_label || item.label; meta.textContent = (item.position || item.projected_range || 'Draft capital') + ' · ' + (item.positional_rank || item.range_confidence || ''); value.textContent = item.trade_value || 0;
      identity.append(name, meta); button.append(identity, value); button.setAttribute('aria-label', 'Add ' + (item.raw_label || item.label) + ' to ' + (team.roster_id === active ? 'assets you send' : 'assets you receive'));
      button.onclick = () => { const partner = document.getElementById('trade-partner'), select = document.getElementById(team.roster_id === active ? 'trade-sent' : 'trade-received'); if (team.roster_id !== active) { partner.value = String(team.roster_id); partner.dispatchEvent(new Event('change')); } select.hidden = false; queueMicrotask(() => { select.value = item.asset_id; select.dispatchEvent(new Event('change')); button.setAttribute('aria-pressed', 'true'); paint(); }); };
      tiles.push(button); group.append(button);
    } grid.append(group);
  }
  if (targetItem && root.dataset.tradeWorkflow === 'trade-for') { const hero = document.createElement('section'), kicker = document.createElement('span'), heading = document.createElement('h3'), context = document.createElement('p'), owner = document.createElement('small'); hero.className = 'ti-target-hero'; kicker.textContent = 'TRADE FOR'; if (targetItem.kind === 'player') { const image = document.createElement('img'); image.src = targetItem.headshot_url; image.alt = ''; hero.append(image); } else { const icon = document.createElement('span'); icon.className = 'ti-pick-icon'; icon.textContent = 'PICK'; hero.append(icon); } heading.textContent = targetItem.raw_label; context.textContent = (targetItem.position || 'Pick') + ' · ' + (targetItem.positional_rank || targetItem.projected_range || '') + ' · DTOS Market ' + targetItem.trade_value; owner.textContent = 'Owned by ' + targetTeam.team_name; hero.prepend(kicker); hero.append(heading, context, owner); browser.before(hero); }
  function applyFilters() { const query = filter.value.trim().toLowerCase(), partnerId = Number(document.getElementById('trade-partner').value || 0); for (const tile of tiles) { const inRoster = rosterScope === 'active' ? Number(tile.dataset.rosterId) === active : Number(tile.dataset.rosterId) === partnerId; const inPosition = position === 'ALL' || tile.dataset.position === position; tile.hidden = !inRoster || !inPosition || (!!query && !tile.textContent.toLowerCase().includes(query)); } for (const group of grid.children) group.hidden = ![...group.querySelectorAll('.ti-asset-tile')].some(tile => !tile.hidden); }
  filter.oninput = applyFilters; document.getElementById('trade-partner').addEventListener('change', applyFilters); applyFilters();
  const balance = document.createElement('section'); balance.className = 'ti-market-balance'; balance.innerHTML = '<h3>Market Balance</h3><div><span>You Send</span><strong id="trade-send-total">0</strong></div><div><span>You Receive</span><strong id="trade-receive-total">0</strong></div><b id="trade-balance-label">ADD ASSETS TO COMPARE</b><small>Neutral market relationship only — team fit and recommendation remain separate.</small>'; root.querySelector('.ti-actions').before(balance);
  function side(selector) { return [...document.querySelectorAll(selector + ' .ti-chip')].reduce((total, chip) => total + (values.get(chip.textContent.replace('×', '').trim()) || 0), 0); }
  function paint() { const sent = side('#trade-sent-chips'), received = side('#trade-received-chips'), ratio = sent && received ? received / sent : 1, selected = new Set([...document.querySelectorAll('.ti-chip')].map(chip => chip.textContent.replace('×', '').trim())); for (const tile of tiles) tile.setAttribute('aria-pressed', String(selected.has(tile.dataset.assetLabel))); document.getElementById('trade-send-total').textContent = sent; document.getElementById('trade-receive-total').textContent = received; document.getElementById('trade-balance-label').textContent = !sent || !received ? 'ADD ASSETS TO COMPARE' : Math.abs(ratio - 1) <= .08 ? 'NEAR FAIR' : ratio > 1 ? 'MARKET FAVORS YOU' : 'MARKET FAVORS THEM'; }
  root.addEventListener('click', () => queueMicrotask(paint)); paint();
});
</script>'''


def _evidence(dossier: TradeDossier) -> str:
    return "".join(
        f"<li><b>{escape(item.factor)}:</b> {escape(item.observed_value)} — {escape(item.explanation)} <small>Source: {escape(item.source)}</small></li>"
        for item in dossier.recommendation.evidence
    )


def trade_card(dossier: TradeDossier, value_impact: dict | None = None) -> str:
    rec, impact, plan = dossier.recommendation, dossier.impact, dossier.negotiation
    strengths = "".join(f"<li>{escape(item)}</li>" for item in dossier.strengths)
    weaknesses = "".join(f"<li>{escape(item)}</li>" for item in dossier.weaknesses)
    risks = "".join(f"<li>{escape(item)}</li>" for item in dossier.risks)
    alternatives = ", ".join(plan.alternative_targets) or "No equivalent cached target"
    market = dossier.market
    market_section = ""
    if market is not None:
        gain = f"{market.market_gain_loss:+d}" if market.market_gain_loss is not None else "Unavailable"
        market_section = f'<section class="ti-section"><h4>Market Intelligence</h4><p><b>Market gain/loss:</b> {gain}</p><p><b>Current consensus:</b> {escape(market.current_consensus)}</p><p><b>Expected movement:</b> {escape(market.expected_movement)}</p><p><b>Potential arbitrage:</b> {escape(market.potential_arbitrage)}</p></section>'
    integrated = ""
    if value_impact:
        integrated = f'<section class="ti-section"><h4>Player Value & Projection Impact</h4><p><b>DTOS Dynasty:</b> {value_impact["dtos_dynasty"]:+.1f}</p><p><b>Market Consensus:</b> {value_impact["market"]:+.1f}</p><p><b>Contender Value:</b> {value_impact["contender"]:+.1f}</p><p><b>Rebuilder Value:</b> {value_impact["rebuild"]:+.1f}</p><p><b>Projected Weekly:</b> {value_impact["weekly"]:+.2f} points</p></section>'
    return f"""
<article class="ti-card"><div class="ti-head"><div><div class="ti-priority">{escape(rec.priority.value)} · {escape(rec.trade_type.value)} · {escape(dossier.proposal.package_type)}</div><h3>{escape(rec.title)}</h3><p class="muted">{escape(dossier.executive_summary)}</p></div><div class="pill">{dossier.partner.compatibility_score}% compatibility<br>{escape(dossier.partner.difficulty)}</div><div class="ti-score">{rec.expected_value:+d}<small>Expected Value</small></div></div>
<div class="ti-assets"><div class="ti-package"><span>Send</span><b>{_assets(dossier.proposal.assets_sent)}</b></div><div class="ti-arrow">→</div><div class="ti-package"><span>Receive</span><b>{_assets(dossier.proposal.assets_received)}</b></div></div>
<div class="ti-metrics"><div class="ti-metric"><b>{impact.current_outlook:+d}</b><span>Current Outlook</span></div><div class="ti-metric"><b>{impact.future_outlook:+d}</b><span>Future Outlook</span></div><div class="ti-metric"><b>{impact.positional_depth:+d}</b><span>Depth</span></div><div class="ti-metric"><b>{impact.asset_value:+d}</b><span>Asset Value</span></div><div class="ti-metric"><b>{rec.confidence}%</b><span>Confidence</span></div></div>
<div class="ti-actions"><button class="ti-action" type="button">Edit Trade</button><button class="ti-action" type="button">Adjust Offer</button><button class="ti-action" type="button">Compare</button></div>
<details class="ti-details"><summary>Open Trade Dossier</summary><div class="ti-grid"><section class="ti-section"><h4>Why Both Sides Improve</h4><p><b>Active:</b> {escape(dossier.why_active_improves)}</p><p><b>Partner:</b> {escape(dossier.why_partner_improves)}</p><p>{escape(dossier.why_realistic)}</p><p>{escape(dossier.why_now)}</p></section><section class="ti-section"><h4>Strengths</h4><ul>{strengths}</ul><h4>Weaknesses</h4><ul>{weaknesses}</ul></section><section class="ti-section"><h4>Risk</h4><ul>{risks}</ul><p>Acceptance likelihood: <b>{rec.acceptance_likelihood if rec.acceptance_likelihood is not None else 'Unavailable'}</b></p></section><section class="ti-section"><h4>Negotiation Plan</h4><p><b>Opening:</b> {escape(plan.opening_offer)}</p><p><b>Minimum offer:</b> {escape(plan.minimum_offer)}</p><p><b>Maximum offer:</b> {escape(plan.maximum_offer)}</p><p><b>Likely counter:</b> {escape(plan.likely_counter)}</p><p><b>Walk-away:</b> {escape(plan.walk_away_point)}</p><p><b>Fallback:</b> {escape(plan.fallback_offer)}</p><p><b>Alternatives:</b> {escape(alternatives)}</p></section>{market_section}{integrated}<section class="ti-section"><h4>Supporting Evidence</h4><ul>{_evidence(dossier)}</ul></section></div></details></article>
"""


def _legacy_trade_center(view: dict) -> str:
    active = view["active_team"]
    unified = view["unified_recommendation"]
    options = "".join(
        f'<option value="{int(team.get("roster_id") or 0)}" {"selected" if int(team.get("roster_id") or 0) == int(active.get("roster_id") or 0) else ""}>{escape(str(team.get("owner") or team.get("team_name")))}</option>'
        for team in view["teams"]
    )
    cards = "".join(trade_card(item, view.get("value_impacts", {}).get(item.partner.roster_id)) for item in view["dossiers"]) or '<div class="card ti-empty">No balanced cached opportunity crossed the v1 generation boundary. Monitor roster and market changes.</div>'
    primary = recommendation_panel(title=unified.title, recommendation=unified.recommendation, confidence=unified.confidence.score, primary_reason=unified.why[0] if unified.why else unified.current_outlook, evidence=unified.why, expected_impact=f"Current: {unified.current_outlook} Future: {unified.future_outlook}", action_label="Review Recommended Offers", action_href="#recommended-offers", limitations=unified.why_not)
    workflows = "".join(
        f'<a class="ti-workflow" href="/trades/{identifier.replace("_", "-")}?front_office={int(active.get("roster_id") or 0)}"><b>{label}</b><span>{description}</span></a>'
        for identifier, label, description in (
            ("create", "Create Trade", "Manually build and evaluate a bilateral proposal."),
            ("trade_for", "Trade For", "Find realistic acquisition paths for another team's asset."),
            ("shop", "Shop Asset", "Find the few legitimate markets for an asset you own."),
            ("recommended", "Recommended Trades", "See worthwhile bilateral opportunities—not a quota."),
        )
    )
    return f"""{TRADE_CSS}<section class="card ti-hero"><div><div class="identity-kicker">Trade Center</div><h2>{escape(str(active.get('team_name') or active.get('owner') or 'Unassigned Franchise'))}</h2><p>Build, negotiate, and evaluate trades through one bilateral intelligence contract.</p></div><form class="ti-selector" method="get"><label for="front_office">Change Front Office</label><select id="front_office" name="front_office" onchange="this.form.submit()">{options}</select></form></section><nav class="ti-workflows" aria-label="Trade workflows">{workflows}</nav>{primary}<div class="ti-list" id="recommended-offers">{cards}</div>"""


def _legacy_trade_workflow(view: dict, workflow: str) -> str:
    labels = {
        "create": ("Create Trade", "Choose two teams, add assets to each side, then evaluate the exact proposal."),
        "trade-for": ("Trade For", "Choose another team's player or pick and search for realistic acquisition paths."),
        "shop": ("Shop Asset", "Choose an asset you own and find the few counterparties with a legitimate reason to engage."),
        "recommended": ("Recommended Trades", "Review only the bilateral opportunities DTOS believes are worth attention."),
    }
    if workflow not in labels:
        raise ValueError("Unknown Trade Center workflow.")
    title, description = labels[workflow]
    active = view["active_team"]
    roster_id = int(active.get("roster_id") or 0)
    intent = {
        "create": "Select teams and assets. Manual proposals remain analyzable even when DTOS flags them as illegal or unrealistic.",
        "trade-for": "Cheapest Plausible, Fair Offer, and Best Offer appear only when each construction legitimately exists.",
        "shop": "Best Overall Return, Win-Now Help, Youth / Rebuild, Draft Capital, Position Need, and Custom are session preferences—not permanent strategy.",
        "recommended": "No quota is filled. A quiet state is the correct result when no proposal clears bilateral quality gates.",
    }[workflow]
    return f"""{TRADE_CSS}<section class="card ti-hero"><div><div class="identity-kicker">Trade Center · {escape(title)}</div><h2>{escape(title)}</h2><p>{escape(description)}</p></div><a class="ti-action" href="/trades?front_office={roster_id}">All Trade Workflows</a></section><section class="card" id="trade-builder" data-trade-workflow="{escape(workflow)}" data-front-office="{roster_id}" data-workspace-endpoint="/api/trades/workspace" data-evaluate-endpoint="/api/trades/evaluate" data-generate-endpoint="/api/trades/generate" data-assist-endpoint="/api/trades/assist"><h3>Start here</h3><p>{escape(intent)}</p><label>Counterparty<select id="trade-partner" aria-label="Counterparty"></select></label><div class="ti-builder"><section class="ti-side"><h4>You send</h4><div class="ti-picker"><select id="trade-sent" aria-label="Asset you send"></select><button class="ti-action" id="trade-add-sent" type="button">+ Add player or pick</button></div><div class="ti-chips" id="trade-sent-chips" aria-label="Assets you send"></div></section><section class="ti-side"><h4>You receive</h4><div class="ti-picker"><select id="trade-received" aria-label="Asset you receive or target"></select><button class="ti-action" id="trade-add-received" type="button">+ Add player or pick</button></div><div class="ti-chips" id="trade-received-chips" aria-label="Assets you receive"></div></section></div><div class="ti-actions"><button class="ti-action" id="trade-run" type="button">{escape('Evaluate Trade' if workflow == 'create' else 'Find Bilateral Options')}</button><button class="ti-action" id="trade-edit" type="button">Edit Trade</button><button class="ti-action" id="trade-adjust" type="button">Adjust Offer</button></div><div class="ti-assist" id="trade-assist" hidden><label for="trade-instruction">How should DTOS adjust it?</label><input id="trade-instruction" placeholder="Don't trade this player. Use a pick instead."><div class="ti-quick"><button type="button" data-adjust="keep this player">Keep this player</button><button type="button" data-adjust="do not trade this pick">Do not trade this pick</button><button type="button" data-adjust="replace this asset">Replace this asset</button><button type="button" data-adjust="use WRs instead">Use WRs instead</button><button type="button" data-adjust="use RBs instead">Use RBs instead</button><button type="button" data-adjust="use picks instead">Use picks instead</button><button type="button" data-adjust="add a pick">Add a pick</button><button type="button" data-adjust="get another player back">Get another player back</button><button type="button" data-adjust="make it cheaper">Make it cheaper</button><button type="button" data-adjust="make it younger">Make it younger</button><button type="button" data-adjust="make it more win-now">Make it more win-now</button><button type="button" data-adjust="expand the trade">Expand the trade</button></div><button class="ti-action" id="trade-apply-adjust" type="button">Generate revised offer</button></div><div class="ti-result" id="trade-result" role="status" aria-live="polite" hidden></div><p class="muted">Ownership is revalidated before evaluation. Market fairness uses neutral canonical values; DTOS fit remains a separate opinion. DTOS analyzes trades but does not submit offers.</p></section><script>
(()=>{{const root=document.getElementById('trade-builder'),partner=document.getElementById('trade-partner'),sent=document.getElementById('trade-sent'),received=document.getElementById('trade-received'),sentChips=document.getElementById('trade-sent-chips'),receivedChips=document.getElementById('trade-received-chips'),result=document.getElementById('trade-result'),assist=document.getElementById('trade-assist'),instruction=document.getElementById('trade-instruction');let workspace=null,last=null;const active=Number(root.dataset.frontOffice),selected={{sent:[],received:[]}};function option(select,value,label){{const row=document.createElement('option');row.value=value;row.textContent=label;select.appendChild(row)}}function team(id){{return workspace?.teams.find(row=>row.roster_id===Number(id))}}function asset(id){{return workspace?.teams.flatMap(row=>row.assets).find(row=>row.asset_id===id)}}function renderChips(side){{const box=side==='sent'?sentChips:receivedChips;box.replaceChildren();for(const id of selected[side]){{const item=asset(id),chip=document.createElement('span'),remove=document.createElement('button');chip.className='ti-chip';chip.textContent=item?.label||id;remove.type='button';remove.textContent='×';remove.setAttribute('aria-label','Remove '+(item?.label||id));remove.onclick=()=>{{selected[side]=selected[side].filter(value=>value!==id);renderChips(side);result.hidden=true}};chip.appendChild(remove);box.appendChild(chip)}}}}function add(side,select){{if(select.value&&!selected.sent.includes(select.value)&&!selected.received.includes(select.value)){{selected[side].push(select.value);renderChips(side);result.hidden=true}}}}function assets(clear=true){{sent.replaceChildren();received.replaceChildren();if(clear)selected.received=[];for(const item of team(active)?.assets||[])option(sent,item.asset_id,item.label);for(const item of team(partner.value)?.assets||[])option(received,item.asset_id,item.label);renderChips('received')}}function payload(){{const workflow=root.dataset.tradeWorkflow.replace('-','_');return {{workflow,active_roster_id:active,partner_roster_id:Number(partner.value),assets_sent:[...selected.sent],assets_received:[...selected.received],asset_id:workflow==='shop'?selected.sent[0]:selected.received[0]}}}}function showEvaluation(e){{result.hidden=false;result.replaceChildren();const title=document.createElement('h4'),reason=document.createElement('p'),values=document.createElement('p'),you=document.createElement('p'),them=document.createElement('p');title.textContent=e.recommendation+' · '+e.perspectives.bilateral_reality;reason.textContent=e.dominant_reason;values.className='ti-values';values.textContent='Market fairness: '+e.values.sent+' sent / '+e.values.received+' received';you.textContent='For your team: '+e.why_you_would_do_it;them.textContent='Why they would do it: '+e.why_they_would_do_it;result.append(title,reason,values,you,them);for(const path of e.repair_paths||[]){{const button=document.createElement('button');button.type='button';button.className='ti-action';button.textContent=path;button.onclick=()=>runAssist(path);result.appendChild(button)}}}}function applyProposal(row){{selected.sent=[...row.proposal.assets_sent];selected.received=[...row.proposal.assets_received];renderChips('sent');renderChips('received');last=row;showEvaluation(row.evaluation)}}function repairMode(text){{const key=text.trim().toLowerCase().replaceAll('-',' ').replaceAll('_',' ').replace(/\\s+/g,' ');return key==='alternative construction'?'ALTERNATIVE_CONSTRUCTION':key==='alternative target'?'ALTERNATIVE_TARGET':'MAKE_THIS_TRADE_WORK'}}async function runAssist(text){{const expected=repairMode(text),response=await fetch(root.dataset.assistEndpoint,{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{...payload(),instruction:text,repair_mode:expected}})}}),body=await response.json();if(!response.ok){{result.hidden=false;result.textContent=body.detail||'Adjustment failed.';return}}const row=body.results?.[0];if(!row){{result.hidden=false;result.textContent=body.quiet_state;return}}if(body.requested_mode!==expected||body.returned_modes?.some(mode=>mode!==expected)||(expected!=='ALTERNATIVE_TARGET'&&(body.target_preserved!==true||row.proposal.assets_received.length!==selected.received.length||row.proposal.assets_received.some(id=>!selected.received.includes(id))))){{result.hidden=false;result.textContent='DTOS rejected a mismatched repair mode.';return}}applyProposal(row)}}function structuredInstruction(action){{if(action==='keep this player'){{const item=selected.sent.map(asset).find(row=>row?.kind==='player');return item?'Keep '+item.label:action}}if(action==='do not trade this pick'){{const item=selected.sent.map(asset).find(row=>row?.kind==='pick');return item?'Do not trade '+item.label:action}}if(action==='replace this asset'){{const item=asset(selected.received[0])||asset(selected.sent[0]);return item?'Replace '+item.label:action}}return action}}fetch(root.dataset.workspaceEndpoint+'?front_office='+active).then(response=>response.json()).then(data=>{{workspace=data;for(const row of data.teams)if(row.roster_id!==active)option(partner,row.roster_id,row.team_name);partner.addEventListener('change',()=>assets(true));assets(false)}}).catch(()=>{{result.hidden=false;result.textContent='Trade workspace is currently unavailable.'}});document.getElementById('trade-add-sent').onclick=()=>add('sent',sent);document.getElementById('trade-add-received').onclick=()=>add('received',received);document.getElementById('trade-run').onclick=async()=>{{if(!workspace||!selected.sent.length||!selected.received.length)return;const p=payload(),manual=p.workflow==='create',response=await fetch(manual?root.dataset.evaluateEndpoint:root.dataset.generateEndpoint,{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify(p)}}),body=await response.json();if(!response.ok){{result.hidden=false;result.textContent=body.detail||'Trade evaluation failed.';return}}const row=manual?body:body.results?.[0];if(row){{last=row;showEvaluation(row.evaluation)}}else{{result.hidden=false;result.textContent=body.quiet_state||'No legitimate construction found.'}}}};document.getElementById('trade-edit').onclick=()=>{{assist.hidden=true;result.hidden=true;sent.focus()}};document.getElementById('trade-adjust').onclick=()=>{{assist.hidden=false;instruction.focus()}};document.querySelectorAll('[data-adjust]').forEach(button=>button.onclick=()=>{{instruction.value=structuredInstruction(button.dataset.adjust)}});document.getElementById('trade-apply-adjust').onclick=()=>runAssist(instruction.value||'make this trade work') }})();
</script>"""


def _canonical_card(row: dict) -> str:
    evaluation, proposal = row["evaluation"], row["proposal"]
    values = evaluation["values"]
    presentation = row.get("proposal_presentation") or {}

    def package(items: list[dict], fallback: tuple[str, ...]) -> str:
        if not items:
            return " + ".join(escape(str(item)) for item in fallback)
        rendered = []
        for item in items:
            kind = str(item.get("kind") or "asset")
            image = (
                f'<img src="{escape(str(item.get("headshot_url")), quote=True)}" alt="" loading="lazy">'
                if kind == "player" and item.get("headshot_url") else
                '<span class="ti-pick-icon" aria-hidden="true">PICK</span>'
            )
            context = " · ".join(filter(None, (
                str(item.get("position") or ""),
                str(item.get("positional_rank") or item.get("projected_range") or ""),
            )))
            rendered.append(
                f'<span class="ti-proposal-asset {"ti-player-tile" if kind == "player" else "ti-pick-tile"}">'
                f'{image}<span><b>{escape(str(item.get("label") or item.get("asset_id") or "Asset"))}</b>'
                f'<small>{escape(context)}</small></span><strong>{int(item.get("market_value") or 0)}</strong></span>'
            )
        return "".join(rendered)

    sent = package(list(presentation.get("send") or ()), tuple(proposal["assets_sent"]))
    received = package(list(presentation.get("receive") or ()), tuple(proposal["assets_received"]))
    best_for = evaluation.get("dimensions", {}).get("best_for", {}).get("active", "UNRESOLVED")
    confidence = evaluation.get("dimensions", {}).get("confidence", {}).get("assessment", "UNRESOLVED")
    partner = str(row.get("partner_team_name") or proposal.get("partner_team_name") or "Trade partner")
    active = str(row.get("active_team_name") or "Your franchise")
    historical = evaluation.get("dimensions", {}).get("historical_counterparty_evidence", {})
    history_reasons = "".join(
        f"<li>{escape(str(reason))}</li>" for reason in historical.get("reasons", ())
    )
    return f'''<article class="ti-card"><div class="ti-head"><div class="ti-opportunity-label"><div class="ti-priority">{escape(str(evaluation["recommendation"]))} · {escape(str(best_for))}</div><div class="ti-confidence">{escape(str(confidence))} confidence</div></div><h3>{escape(str(evaluation["dominant_reason"]))}</h3></div><div class="ti-franchises"><div class="ti-franchise"><b>{escape(active)}</b><span>Receives</span></div><div class="ti-arrow">⇄</div><div class="ti-franchise"><b>{escape(partner)}</b><span>Sends</span></div></div><div class="ti-assets"><div class="ti-package"><span>You send</span>{sent}</div><div class="ti-arrow">→</div><div class="ti-package"><span>You receive</span>{received}</div></div><div class="ti-values"><span>Neutral market: <b>{values["sent"]}</b> sent / <b>{values["received"]}</b> received</span><span>{escape(str(evaluation["perspectives"]["bilateral_reality"]))}</span></div><div class="ti-bilateral"><div class="ti-reason"><span>Why you should consider this</span>{escape(str(evaluation["why_you_would_do_it"]))}</div><div class="ti-reason"><span>Why they should consider this</span>{escape(str(evaluation["why_they_would_do_it"]))}</div></div><a class="ti-card-action" href="/trades/create">View trade details →</a><details class="ti-details"><summary>Evidence and constraints</summary><p><b>Why now:</b> {escape(str(evaluation.get("why_now") or "No supported timing signal."))}</p><p><b>Historical counterparty evidence:</b> {escape(str(historical.get("assessment") or "INSUFFICIENT EVIDENCE"))} · {escape(str(historical.get("confidence") or "LOW"))} confidence</p><ul>{history_reasons}</ul><p>Package quality, optimal legal lineup effects, counterparty plausibility, and evidence confidence are included in the canonical evaluation. Historical evidence is context, not a promise of acceptance.</p></details></article>'''


def trade_center(view: dict) -> str:
    active = view["active_team"]
    unified = view["unified_recommendation"]
    active_id = int(active.get("roster_id") or 0)
    options = "".join(
        f'<option value="{int(team.get("roster_id") or 0)}" {"selected" if int(team.get("roster_id") or 0) == active_id else ""}>{escape(str(team.get("owner") or team.get("team_name")))}</option>'
        for team in view["teams"]
    )
    workflows = "".join(
        f'<a class="ti-workflow" href="/trades/{identifier}?front_office={active_id}"><b>{label}</b><span>{description}</span></a>'
        for identifier, label, description in (
            ("create", "Create Trade", "Build, evaluate, and improve a bilateral proposal."),
            ("trade-for", "Trade For", "Pursue an asset another franchise owns."),
            ("shop", "Shop Asset", "Search the league for legitimate markets."),
            ("recommended", "Recommended Trades", "Only worthwhile bilateral opportunities."),
        )
    )
    cards = "".join(_canonical_card(row) for row in view.get("canonical_results", ()))
    if not cards:
        cards = '<div class="card ti-empty"><div><div class="ds-eyebrow">No clean trade right now</div><h3>No realistic bilateral opportunity clears every gate.</h3><p>DTOS checked neutral market value, roster effects, package quality, counterparty fit, and evidence confidence. Try building a proposal or targeting a specific asset.</p><div class="ti-actions"><a class="ti-action" href="/trades/create">Create a Trade</a><a class="ti-action" href="/trades/trade-for">Trade For a Player</a></div></div></div>'
    first = (view.get("canonical_results") or [None])[0]
    if first:
        evaluation = first["evaluation"]
        primary_title = "A bilateral trade is worth reviewing"
        primary_recommendation = str(evaluation["recommendation"])
        primary_reason = str(evaluation["dominant_reason"])
        primary_evidence = (
            str(evaluation["why_you_would_do_it"]),
            str(evaluation["why_they_would_do_it"]),
        )
        expected_impact = str(evaluation["perspectives"]["bilateral_reality"])
    else:
        primary_title = "No trade needs your attention right now"
        primary_recommendation = "KEEP SEARCHING"
        primary_reason = "No current package clears neutral-market, roster-fit, package-quality, and counterparty gates."
        primary_evidence = ("DTOS completed the current bilateral search without filling a recommendation quota.",)
        expected_impact = "Your roster remains unchanged."
    primary = recommendation_panel(
        title=primary_title, recommendation=primary_recommendation,
        confidence=unified.confidence.score,
        primary_reason=primary_reason,
        evidence=primary_evidence,
        expected_impact=expected_impact,
        action_label="Review Recommended Offers", action_href="#recommended-offers",
        limitations=unified.why_not,
    )
    return f'''{TRADE_CSS}<section class="card ti-hero"><div><div class="identity-kicker">Trade Center</div><h2>{escape(str(active.get("team_name") or active.get("owner") or "Unassigned Franchise"))}</h2><p>Neutral market value and team-specific fit are evaluated separately.</p></div><form class="ti-selector" method="get"><label>Active Front Office<select name="front_office" onchange="this.form.submit()">{options}</select></label></form></section><nav class="ti-workflows">{workflows}</nav>{primary}<div class="ti-list" id="recommended-offers">{cards}</div>'''


def trade_workflow(
    view: dict, workflow: str, preload_asset_id: str | None = None,
    owner_roster_id: int | None = None,
) -> str:
    labels = {
        "create": ("Create Trade", "Build an exact proposal, then review calculated alternatives."),
        "trade-for": ("Trade For", "Pursue the selected asset through its current owner."),
        "shop": ("Shop Asset", "Search every legitimate counterparty for the selected asset."),
        "recommended": ("Recommended Trades", "Review only opportunities that clear bilateral quality gates."),
    }
    if workflow not in labels:
        raise ValueError("Unknown Trade Center workflow.")
    title, description = labels[workflow]
    active_id = int(view["active_team"].get("roster_id") or 0)
    preload = escape(preload_asset_id or "", quote=True)
    owner_id = int(owner_roster_id or 0)
    run_label = "Evaluate Trade" if workflow == "create" else "Find Bilateral Options"
    return f'''{TRADE_CSS}<style>.ti-picker select,.ti-picker button{{min-height:44px}}.ti-options{{display:grid;gap:10px;margin-top:12px}}.ti-option{{border:1px solid var(--line);border-radius:10px;padding:12px;background:#07111f}}.ti-alternatives{{margin-top:16px;border-top:1px solid var(--line);padding-top:12px}}.ti-error{{color:#ffb4a8}}</style><section class="card ti-hero"><div><div class="identity-kicker">Trade Center · {escape(title)}</div><h2>{escape(title)}</h2><p>{escape(description)}</p></div><a class="ti-action" href="/trades?front_office={active_id}">All Trade Workflows</a></section><section class="card" id="trade-builder" data-trade-workflow="{escape(workflow)}" data-front-office="{active_id}" data-preload-asset="{preload}" data-owner-roster="{owner_id}" data-workspace-endpoint="/api/trades/workspace" data-evaluate-endpoint="/api/trades/evaluate" data-generate-endpoint="/api/trades/generate" data-assist-endpoint="/api/trades/assist" data-alternatives-endpoint="/api/trades/alternatives"><label>Counterparty<select id="trade-partner"></select></label><div class="ti-builder"><section class="ti-side"><h4>You send</h4><div class="ti-picker"><button class="ti-action" id="trade-add-sent" type="button">+ Add player or pick</button><select id="trade-sent" hidden></select></div><div class="ti-chips" id="trade-sent-chips"></div></section><section class="ti-side"><h4>You receive</h4><div class="ti-picker"><button class="ti-action" id="trade-add-received" type="button">+ Add player or pick</button><select id="trade-received" hidden></select></div><div class="ti-chips" id="trade-received-chips"></div></section></div><div class="ti-actions"><button class="ti-action" id="trade-run" type="button">{escape(run_label)}</button><button class="ti-action" id="trade-edit" type="button">Edit Trade</button><button class="ti-action" id="trade-adjust" type="button">Adjust Offer</button></div><div class="ti-assist" id="trade-assist" hidden><label>How should DTOS adjust it?<input id="trade-instruction" placeholder="Don't trade this player. Use a pick instead."></label><div class="ti-quick"><button type="button" data-adjust="keep this player">Keep this player</button><button type="button" data-adjust="make it cheaper">Make it cheaper</button><button type="button" data-adjust="make it younger">Make it younger</button><button type="button" data-adjust="make it more win-now">Make it more win-now</button></div><details><summary>More adjustment options</summary><div class="ti-quick"><button type="button" data-adjust="do not trade this pick">Do not trade this pick</button><button type="button" data-adjust="replace this asset">Replace this asset</button><button type="button" data-adjust="use WRs instead">Use WRs instead</button><button type="button" data-adjust="use RBs instead">Use RBs instead</button><button type="button" data-adjust="use picks instead">Use picks instead</button><button type="button" data-adjust="add a pick">Add a pick</button><button type="button" data-adjust="get another player back">Get another player back</button><button type="button" data-adjust="expand the trade">Expand the trade</button></div></details><button class="ti-action" id="trade-apply-adjust" type="button">Generate revised offer</button></div><div class="ti-result" id="trade-result" role="status" aria-live="polite" hidden></div><section class="ti-alternatives" id="trade-alternatives" hidden><h3>Other Ways to Make This Deal</h3><label>Change protected asset<select id="trade-protected"></select></label><div class="ti-options" id="trade-alternative-list"></div></section><p class="muted">Ownership is revalidated before evaluation. Market fairness uses neutral canonical values; team-specific fit remains separate. DTOS analyzes trades but does not submit offers.</p></section><script>
(()=>{{/* repair buttons preserve the established runAssist(path) contract */const r=document.getElementById('trade-builder'),p=document.getElementById('trade-partner'),s=document.getElementById('trade-sent'),g=document.getElementById('trade-received'),out=document.getElementById('trade-result'),assist=document.getElementById('trade-assist'),instruction=document.getElementById('trade-instruction'),alts=document.getElementById('trade-alternatives'),altList=document.getElementById('trade-alternative-list'),protect=document.getElementById('trade-protected');let w=null;const active=Number(r.dataset.frontOffice),flow=r.dataset.tradeWorkflow.replace('-','_'),chosen={{sent:[],received:[]}};function opt(el,id,label,placeholder=false){{const o=document.createElement('option');o.value=id;o.textContent=label;o.disabled=placeholder;o.selected=placeholder;el.appendChild(o)}}function team(id){{return w?.teams.find(x=>x.roster_id===Number(id))}}function asset(id){{return w?.teams.flatMap(x=>x.assets).find(x=>x.asset_id===id)}}function chips(side){{const box=document.getElementById('trade-'+side+'-chips');box.replaceChildren();for(const id of chosen[side]){{const c=document.createElement('span'),b=document.createElement('button'),label=asset(id)?.label||id;c.className='ti-chip';c.append(document.createTextNode(label));b.type='button';b.textContent='×';b.setAttribute('aria-label','Remove '+label);b.onclick=()=>{{chosen[side]=chosen[side].filter(x=>x!==id);chips(side)}};c.appendChild(b);box.appendChild(c)}}}}function error(text){{out.hidden=false;out.classList.add('ti-error');out.textContent=text}}function add(side,el){{const id=el.value;if(!id)return;if(chosen.sent.includes(id)||chosen.received.includes(id))return error('That asset is already in this proposal.');chosen[side].push(id);chips(side);el.hidden=true;el.selectedIndex=0}}function fill(clear=true){{s.replaceChildren();g.replaceChildren();opt(s,'','Choose an asset you own',true);opt(g,'','Choose an asset they own',true);if(clear)chosen.received=[];for(const x of team(active)?.assets||[])opt(s,x.asset_id,x.label);for(const x of team(p.value)?.assets||[])opt(g,x.asset_id,x.label);chips('received')}}function payload(){{return {{workflow:flow,active_roster_id:active,partner_roster_id:Number(p.value),assets_sent:[...chosen.sent],assets_received:[...chosen.received],asset_id:flow==='shop'?chosen.sent[0]:chosen.received[0]}}}}function evaluation(e,label=''){{out.hidden=false;out.classList.remove('ti-error');out.replaceChildren();const lines=[(label?label+' · ':'')+e.recommendation+' · '+e.perspectives.bilateral_reality,e.dominant_reason,'Neutral market: '+e.values.sent+' sent / '+e.values.received+' received','For your team: '+e.why_you_would_do_it,'Why they may engage: '+e.why_they_would_do_it];lines.forEach((text,index)=>{{const node=document.createElement(index===0?'h4':'p');node.textContent=text;out.appendChild(node)}});for(const path of e.repair_paths||[]){{const button=document.createElement('button');button.className='ti-action';button.textContent=path;button.onclick=()=>runAssist(path);out.appendChild(button)}}}}function open(row){{p.value=String(row.proposal.partner_roster_id);fill(false);chosen.sent=[...row.proposal.assets_sent];chosen.received=[...row.proposal.assets_received];chips('sent');chips('received');evaluation(row.evaluation,row.alternative_type||row.offer_level||'')}}function options(rows){{out.hidden=false;out.replaceChildren();const box=document.createElement('div');box.className='ti-options';for(const row of rows){{const card=document.createElement('article'),h=document.createElement('h4'),copy=document.createElement('p'),button=document.createElement('button'),send=(row.proposal_presentation?.send||[]).map(x=>x.label).join(' + '),receive=(row.proposal_presentation?.receive||[]).map(x=>x.label).join(' + ');card.className='ti-option';h.textContent=row.offer_level||row.partner_team_name||'Bilateral option';copy.textContent='Send '+send+' → Receive '+receive+' · '+row.evaluation.recommendation+' · '+row.evaluation.dominant_reason;button.className='ti-action';button.textContent='Open editable offer';button.onclick=()=>open(row);card.append(h,copy,button);box.appendChild(card)}}out.appendChild(box)}}async function alternatives(){{const response=await fetch(r.dataset.alternativesEndpoint,{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{...payload(),protected_asset_id:protect.value||undefined}})}}),body=await response.json();alts.hidden=false;altList.replaceChildren();if(!body.results?.length){{altList.textContent=body.quiet_state||body.detail||'No distinct legitimate alternative is available.';return}}for(const row of body.results){{const card=document.createElement('article'),h=document.createElement('h4'),copy=document.createElement('p'),button=document.createElement('button'),send=(row.proposal_presentation?.send||[]).map(x=>x.label).join(' + '),receive=(row.proposal_presentation?.receive||[]).map(x=>x.label).join(' + ');card.className='ti-option';h.textContent=row.alternative_type;copy.textContent='Send '+send+' → Receive '+receive+' · '+row.evaluation.dominant_reason;button.className='ti-action';button.textContent='Open editable alternative';button.onclick=()=>open(row);card.append(h,copy,button);altList.appendChild(card)}}}}function repairMode(text){{const key=text.trim().toLowerCase().replaceAll('-',' ').replaceAll('_',' ').replace(/\\s+/g,' ');return key==='alternative construction'?'ALTERNATIVE_CONSTRUCTION':key==='alternative target'?'ALTERNATIVE_TARGET':'MAKE_THIS_TRADE_WORK'}}async function runAssist(text){{const expected=repairMode(text),response=await fetch(r.dataset.assistEndpoint,{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{...payload(),instruction:text,repair_mode:expected}})}}),body=await response.json();if(!response.ok)return error(body.detail||'Adjustment failed.');const row=body.results?.[0];if(!row)return error(body.quiet_state||'No legitimate target-preserving revision found.');if(body.requested_mode!==expected||body.returned_modes?.some(mode=>mode!==expected)||(expected!=='ALTERNATIVE_TARGET'&&(body.target_preserved!==true||row.proposal.assets_received.length!==chosen.received.length||row.proposal.assets_received.some(id=>!chosen.received.includes(id)))))return error('DTOS rejected a mismatched repair mode.');open(row)}}async function run(){{if(!w)return;const bodyPayload=payload();if(flow==='create'&&(!bodyPayload.assets_sent.length||!bodyPayload.assets_received.length))return error('Add at least one asset to each side.');const response=await fetch(flow==='create'?r.dataset.evaluateEndpoint:r.dataset.generateEndpoint,{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify(bodyPayload)}}),body=await response.json();if(!response.ok)return error(body.detail||'Ownership changed or evaluation failed.');if(flow==='create'){{evaluation(body.evaluation);protect.replaceChildren();for(const id of chosen.sent)opt(protect,id,asset(id)?.label||id);await alternatives()}}else body.results?.length?options(body.results):error(body.quiet_state||'No legitimate bilateral path exists.')}}fetch(r.dataset.workspaceEndpoint+'?front_office='+active).then(x=>x.json()).then(async data=>{{w=data;for(const x of data.teams)if(x.roster_id!==active)opt(p,x.roster_id,x.team_name);const owner=Number(r.dataset.ownerRoster),preload=r.dataset.preloadAsset;if(owner&&owner!==active&&[...p.options].some(x=>Number(x.value)===owner))p.value=String(owner);p.onchange=()=>fill(true);fill(false);if(preload){{const side=flow==='shop'?'sent':'received',el=side==='sent'?s:g;if([...el.options].some(x=>x.value===preload)){{chosen[side]=[preload];chips(side);await run()}}else error('The selected asset is no longer owned in this league context.')}}}}).catch(()=>error('Trade workspace is currently unavailable.'));s.onchange=()=>add('sent',s);g.onchange=()=>add('received',g);document.getElementById('trade-add-sent').onclick=()=>{{s.hidden=false;s.focus()}};document.getElementById('trade-add-received').onclick=()=>{{g.hidden=false;g.focus()}};document.getElementById('trade-run').onclick=run;document.getElementById('trade-edit').onclick=()=>{{assist.hidden=true;s.focus()}};document.getElementById('trade-adjust').onclick=()=>{{assist.hidden=false;instruction.focus()}};document.querySelectorAll('[data-adjust]').forEach(b=>b.onclick=()=>instruction.value=b.dataset.adjust);document.getElementById('trade-apply-adjust').onclick=()=>runAssist(instruction.value||'make this trade work');protect.onchange=alternatives}})();
</script>{_premium_trade_enhancement()}'''
